{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required_symbols = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}

    retained = set()
    pending = [
        node["id"]
        for node in nodes
        if not node.get("removable", False)
        or node.get("symbol") in required_symbols
    ]

    while pending:
        node_id = pending.pop()
        if node_id in retained:
            continue
        retained.add(node_id)
        node = by_id.get(node_id)
        if node is not None:
            parent_id = node.get("parent")
            if parent_id is not None and parent_id in by_id:
                pending.append(parent_id)

    return {
        "removed_node_ids": [
            node["id"] for node in nodes if node["id"] not in retained
        ],
        "retained_node_ids": [
            node["id"] for node in nodes if node["id"] in retained
        ],
    }
"}
